/**
 * The app's document language; read on every call because the app sets
 * `<html lang>` after client plugins are applied.
 * @returns `zh` or `en`.
 */
export function currentLanguage(): 'zh' | 'en' {
  const language = (globalThis.document?.documentElement.lang || globalThis.navigator?.language || 'en').toLowerCase()
  return language.startsWith('zh') ? 'zh' : 'en'
}
